# Test cases for TestFindRoute_SingleSource.
# Fields: name  path  lr_exact  lr_wild  want
# Use "-" for empty lr_exact or lr_wild; "-" in want means no route expected.

exact_path_wins                  /exact         lr1  -    be_exact_r1
longest_prefix                   /api/v2/foo    lr1  -    be_r1_apiv2
shorter_prefix                   /api/foo       lr1  -    be_r1_api
regex_when_nothing_else_matches  /123           lr1  -    be_r1_digits
no_match_returns_no_route        /nowhere       lr1  -    -
wildcard_source_only             /special/x     -    lr2  be_r2_special
wildcard_default_prefix          /anything      -    lr2  be_r2_default
prefix_needs_element_boundary    /apiexample    lr1  -    -
longer_prefix_non_boundary_falls_back  /api/v2example  lr1  -    be_r1_api

# Regex keys in the generated form: the listener-route identity, then the
# path regex in a group.
regex_escaped_dot_matches_a_dot          /files/a.php   lr1  -    be_r1_php
regex_escaped_dot_is_literal             /files/aXphp   lr1  -    -
regex_plain_dot_matches_any_character    /any/aXb       lr1  -    be_r1_anychar
regex_alternation_first                  /alt/x         lr1  -    be_r1_alt
regex_alternation_second                 /alt/y         lr1  -    be_r1_alt
regex_alternation_needs_the_identity     /alt/y         lr9  -    -
